"""Regenerates lib/demo/prototype-src.ts from the prototype's js folder.
Usage: python scripts/embed-prototype.py "<path to GRID Feasibility Studio Prototype - 2026-10-19/js>" """
import json, sys
src = sys.argv[1]
files = ["options.js", "field-dictionary.js", "broker-tags.js", "engine.js", "quick.js"]
out = ['/**', ' * GRID prototype engine sources (intake: "GRID Feasibility Studio Prototype - 2026-10-19/js"), embedded as',
       ' * strings so the demo stand-in pipeline can run them in a sandbox (lib/demo/engine.ts). Generated by',
       ' * scripts/embed-prototype.py; do not edit by hand. The prototype builds every report from the inputs only',
       ' * and labels its output "Prototype".', ' */',
       'export const PROTOTYPE_SOURCES: [name: string, code: string][] = [']
for f in files:
    out.append(f'  [{json.dumps(f)}, {json.dumps(open(src + "/" + f, encoding="utf-8").read())}],')
out.append('];')
open("lib/demo/prototype-src.ts", "w", encoding="utf-8").write("\n".join(out) + "\n")
